(370, '_site_transient_feed_868981a74fb045e2d866f14ee0dbf978', 'a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:49:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n		\n		\n		\n		\n		\n		\n		\n		\n		\n	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:19:\"WordPress  Türkiye\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:21:\"https://www.wp-tr.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"WordPress Türkiye Resmi sitesi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:13:\"lastBuildDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 01 Jul 2024 22:41:02 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"tr\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"generator\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://wordpress.org/?v=7.1.3\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"WordCamp Avrupa 2024’ün Kısa Özeti\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://www.wp-tr.org/wordcamp-avrupa-2024un-kisa-ozeti/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 01 Jul 2024 08:40:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20531\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:498:\"Bu yıl 12. düzenlenen WordCamp Avrupa, 2.584 kişinin katılımıyla, Lingotto Konferans ve Sergi Salonu&#8216;nda, Torino, İtalya&#8217;da gerçekleşti. Etkinliği sizlere aktarabilmek için Güzel Hosting sponsorluğunda WordPress Türkiye olarak oradaydık. 13-15 Haziran 2024 tarihleri arasında, dünyanın bir çok ülkesinden Torino&#8217;ya akın eden WordPress severler, dünyanın en popüler web platformunu keşfetmek ve kutlamak için bir araya geldiler. Gönüllülerden [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:14181:\"\n<p class=\"wp-block-paragraph\">Bu yıl 12. düzenlenen WordCamp Avrupa, 2.584 kişinin katılımıyla, <a href=\"https://europe.wordcamp.org/2024/venue/\" target=\"_blank\" rel=\"noreferrer noopener\">Lingotto Konferans ve Sergi Salonu</a>&#8216;nda, Torino, İtalya&#8217;da gerçekleşti.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><img fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/wceu-torino-night-1024x683.webp\" alt=\"WordCamp Avrupa 2024\'ü kutlamak için aydınlatılan Torino\'daki Mole Antonelliana.\" class=\"wp-image-20532\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/wceu-torino-night-1024x683.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/wceu-torino-night-200x133.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/wceu-torino-night-768x512.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/wceu-torino-night.webp 1080w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">WordCamp Avrupa 2024&#8217;ü kutlamak için aydınlatılan Torino&#8217;daki Mole Antonelliana.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Etkinliği sizlere aktarabilmek için <a href=\"https://www.guzel.net.tr\" data-type=\"link\" data-id=\"https://www.guzel.net.tr\" target=\"_blank\" rel=\"noreferrer noopener\">Güzel Hosting</a> sponsorluğunda WordPress Türkiye olarak oradaydık. 13-15 Haziran 2024 tarihleri arasında, dünyanın bir çok ülkesinden Torino&#8217;ya akın eden WordPress severler, dünyanın en popüler web platformunu keşfetmek ve kutlamak için bir araya geldiler. Gönüllülerden oluşan 250 kişilik bir ekip, kıdemli WordCamp organizatörleri Wendie Huis in ‘t Veld, Juan Hernando ve Takis Bouyouris yönetiminde etkinliği düzenlediler.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Katılımcı Günü&#8217;nün Büyük Etkisi</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://europe.wordcamp.org/2024/contributor-day/\" target=\"_blank\" rel=\"noreferrer noopener\">Katılımcı Günü</a>, WordPress&#8217;i geliştirmek ve desteklemek için 25 ekipte toplam 726 katılımcıyı bir araya getirdi. Katılımcılar 29 dilde 79.059 metnin çevrilmesi, yaklaşan 6.6 sürümü için belgelerin güncellenmesi, destek forumlarında etkinlik, test ekipleri için yeni katılımcıların ekibe katılması ve eklenti güvenliğini artırma yollarının belirlenmesi gibi çok çeşitli alanlarda çalışmalar sağladı.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><img decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/katilimcilar-1024x683.webp\" alt=\"WCEU 2024 Katkı Günü\'nde toplanan katılımcılar.\" class=\"wp-image-20533\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/katilimcilar-1024x683.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/katilimcilar-200x133.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/katilimcilar-768x512.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/katilimcilar-1536x1024.webp 1536w, https://www.wp-tr.org/wp-content/uploads/2024/07/katilimcilar-2048x1366.webp 2048w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">WCEU 2024 Katkı Günü&#8217;nde toplanan katılımcılar.</figcaption></figure>\n</div>\n\n\n<h2 class=\"wp-block-heading\">Sürdürülebilir Açık Kaynak Gelecektir</h2>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><img decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/birinci-gun-keynote-1024x576.webp\" alt=\"Açılış konuşması sunucuları, Joost de Valk and Juliette Reinders Folmer\" class=\"wp-image-20534\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/birinci-gun-keynote-1024x576.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/birinci-gun-keynote-200x113.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/birinci-gun-keynote-768x432.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/birinci-gun-keynote-1536x864.webp 1536w, https://www.wp-tr.org/wp-content/uploads/2024/07/birinci-gun-keynote.webp 1920w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">Açılış konuşması sunucuları, Joost de Valk and Juliette Reinders Folmer</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Joost de Valk ve Juliette Reinders Folmer, açık kaynak yazılım projelerinin sürdürülebilirliğini konu alan açılış konuşmasını yaptılar. Konuşmalarında açık kaynak projelerinin finansmanı, kod dışındaki katkılar ve ticari işletmelerde, müşterileri açık kaynağın tescilli platformlara uygun bir alternatif olduğuna ikna etme konularını ele aldılar.</p>\n\n\n\n<h2 class=\"wp-block-heading\">İki Gün Süren İlgi Çekici Oturumlar</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Cuma ve Cumartesi günlerinde, üç ayrı kolda toplam 60 sunum ve atölye çalışması gerçekleştirildi. Konular arasında WordPress geliştirme, erişilebilirlik, tasarım, iş dünyası, topluluk, yapay zeka ve siber güvenlik yer aldı.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\"><div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large is-resized\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo2-1024x683.webp\" alt=\"\" class=\"wp-image-20536\" style=\"width:auto;height:250px\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo2-1024x683.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo2-200x133.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo2-768x512.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo2-1536x1024.webp 1536w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo2-2048x1365.webp 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">Hızlı Oluşturma Oturumu</figcaption></figure>\n</div></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\"><div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large is-resized\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"783\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo1-1024x783.webp\" alt=\"Bağlantı Serisi\" class=\"wp-image-20535\" style=\"width:auto;height:250px\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo1-1024x783.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo1-200x153.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo1-768x587.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/session-photo1.webp 1404w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">Bağlantı Serisi</figcaption></figure>\n</div></div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Gençlik atölyesi, genç katılımcılara WordPress siteleri oluşturma, yeni teknolojileri keşfetme ve internet güvenliği hakkında bilgi edinme fırsatları sundu. Bu arada, sağlıklı yaşam temalı bir kolda, yoga dersleri ve Torino&#8217;da yürüyüş turları içeriyordu; katılımcıları ekranlarından uzaklaşmaya ve bu yılın ev sahibi şehrinin güzelliklerini keşfetmeye teşvik etti.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Yıl Ortası Proje Güncellemesi</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress&#8217;in kurucu ortağı Matt Mullenweg, WordPress ile ilgili <a href=\"https://www.youtube.com/watch?v=ELW4Jdvujbc\" target=\"_blank\" rel=\"noreferrer noopener\">yıl ortası proje güncellemesini</a> paylaştı ve sunumunu, Gutenberg aşamalarından WordPress Playground&#8217;a kadar çeşitli konularda seyircilerden gelen soruları yanıtlayarak ve bir hata düzeltme talebinin hızlandırılmasını kabul ederek tamamladı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Matt&#8217;in sunumu, <a href=\"https://make.wordpress.org/community/2024/06/15/wordpress-contributor-mentorship-program-q4-2024-call-for-interest/\" target=\"_blank\" rel=\"noreferrer noopener\">katılımcı mentorluk programı</a>nın ve WCEU Katılımcı Günü’nün başarısını vurguladı, Canlı Çeviri&#8217;yi tanıttı ve <a href=\"https://wordpress.org/data-liberation/\" target=\"_blank\" rel=\"noreferrer noopener\">Veri Özgürlüğü</a> girişimi hakkında bir güncelleme paylaştı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Matt ayrıca <a href=\"https://wordpress.org/playground/\">WordPress Playground</a> ile ilgili en son yenilikleri ele aldı, <a href=\"https://wordpress.org/news/2024/04/how-wordpress-is-creating-a-faster-web/\" target=\"_blank\" rel=\"noreferrer noopener\">performans kazanımları</a>nı vurguladı ve otomatik güncellemeler için geri alma ve uzaktan görüntüleme gibi gelecekteki sürümlerde beklenen özelliklerin önizlemesini yaptı.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/matt-1024x683.webp\" alt=\"WordPress kurucu ortağı Matt Mullenweg\" class=\"wp-image-20537\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/matt-1024x683.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/matt-200x133.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/matt-768x512.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/matt-1536x1024.webp 1536w, https://www.wp-tr.org/wp-content/uploads/2024/07/matt-2048x1365.webp 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">WordPress kurucu ortağı Matt Mullenweg</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">WordPress topluluğunda heyecan verici yeni bir trende dikkat çeken Mullenweg, WordPress uzmanlarının gerçek zamanlı olarak web siteleri oluşturduğu, ipuçlarını, kısayolları ve en iyi uygulamaları sergilediği &#8220;hızlı oluşturma yarışmaları&#8221;ndan bahsetti. Bu tür bir etkinlik WCEU oturumlarından birinde gerçekleşti ve Matt&#8217;in sunumunun soru-cevap bölümünde, böyle bir etkinliğe katılması için bir meydan okumayı kabul etti!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Matt, 2003&#8217;te Mike Little ile birlikte ilk sürümü başlattığından bu yana WordPress&#8217;in 21. yıldönümüne ulaşmasını değerlendirdi. WordPress&#8217;in önümüzdeki on yıllar boyunca sürdürülebilir kalmasını sağlamak için <a href=\"https://ma.tt/2024/05/wp21/\">11 önemli madde</a>yi paylaştı:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Basit şeyler kolay ve sezgisel olmalı, karmaşık şeyler mümkün olmalı.</li>\n\n\n\n<li>Bloglar ve dinamik siteler daha iyidir.</li>\n\n\n\n<li>Belgelerin Wiki&#8217;ler kadar kolay düzenlenebilir olması gerekir.</li>\n\n\n\n<li>Forumlar ön planda ve merkezi bir konumda olmalıdır.</li>\n\n\n\n<li>Eklentiler ve temalar topluluk altyapısı ile birlikte gelmelidir.</li>\n\n\n\n<li>Harika tema önizlemeleri ve çeşitli estetikler sunulmalıdır.</li>\n\n\n\n<li>Rehberler ve gereksinimler için aşırıya kaçmamalıyız.</li>\n\n\n\n<li>Geri bildirim döngüleri çok önemlidir.</li>\n\n\n\n<li>Çekirdek, belirgin görüşlere sahip ve tuhaf olmalıdır.</li>\n\n\n\n<li>WordPress yapıyorsanız, WordPress kullanın.</li>\n\n\n\n<li>Son kullanıcılarımıza yakın kalın.</li>\n</ul>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n<iframe loading=\"lazy\" class=\"youtube-player\" width=\"640\" height=\"360\" src=\"https://www.youtube.com/embed/ELW4Jdvujbc?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=tr-TR&#038;autohide=2&#038;wmode=transparent\" allowfullscreen=\"true\" style=\"border:0;\" sandbox=\"allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox\"></iframe>\n</div><figcaption class=\"wp-element-caption\">WordPress Yaz Güncellemesi</figcaption></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Kapanış Konuşmaları</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Kapanış konuşmalarında, etkinlik organizatörleri Avrupa Parlamentosu, Torino şehri ve bölgesel turizm kurulu Turismo Torino&#8217;nun destekleri için teşekkürlerini ifade ettiler. Gönüllüler ekibi, etkinliği üretmedeki özverili çalışmaları nedeniyle kutlandı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Üç günlük yoğun bir programı sonlandıran organizasyon ekibi, WordCamp Europe 2025&#8217;in 5-7 Haziran 2025 tarihleri arasında Basel, İsviçre&#8217;de düzenleneceğini duyurdu. Duyuru büyük alkışlarla karşılandı ve bir yıl sonra tekrar buluşma planları yapıldı.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"682\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/07/group-1024x682.webp\" alt=\"\" class=\"wp-image-20538\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/07/group-1024x682.webp 1024w, https://www.wp-tr.org/wp-content/uploads/2024/07/group-200x133.webp 200w, https://www.wp-tr.org/wp-content/uploads/2024/07/group-768x512.webp 768w, https://www.wp-tr.org/wp-content/uploads/2024/07/group-1536x1024.webp 1536w, https://www.wp-tr.org/wp-content/uploads/2024/07/group-2048x1365.webp 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /><figcaption class=\"wp-element-caption\">WCEU grup fotoğrafı</figcaption></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n\n\n\n<p class=\"wp-block-paragraph\">Bu yazı <a href=\"https://wordpress.org/news/2024/06/highlights-from-wordcamp-europe-2024/\" target=\"_blank\" rel=\"noreferrer noopener\">https://wordpress.org/news/2024/06/highlights-from-wordcamp-europe-2024/</a> adresindeki yazının Türkçe&#8217;ye çevrilmiş ve editöryel olarak elden geçirilmiş sürümüdür.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20531\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:25:\"Sayılarla Güzel Hosting\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"https://www.wp-tr.org/sayilarla-guzel-hosting/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 14 Jun 2024 13:30:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20526\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:486:\"Sayılarla WordCamp Avrupa 2023 yazımızda geçen yıla ait istatistikler paylaşmıştık. Bu yazımızda sponsorumuz olan Güzel Hosting ile ilgili çeşitli istatistikleri paylaşacağız. Güzel Hosting, 2008 yılından bu yana &#8220;en uygun ücretlerle en iyi hizmeti sunabilmek&#8221; anlayışıyla faaliyet göstermektedir. Bu anlayış sayesinde sektörde 16 yılı aşkın süredir öncü bir konuma gelmiş bulunmaktadır. Müşterilerinin iş ve web sitelerinin [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2933:\"\n<p class=\"wp-block-paragraph\"><a href=\"https://www.wp-tr.org/sayilarla-wordcamp-avrupa-2023/\">Sayılarla WordCamp Avrupa 2023</a> yazımızda geçen yıla ait istatistikler paylaşmıştık. Bu yazımızda sponsorumuz olan <a href=\"https://www.guzel.net.tr\">Güzel Hosting</a> ile ilgili çeşitli istatistikleri paylaşacağız.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-scaled.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"760\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-1024x760.jpg\" alt=\"\" class=\"wp-image-20528\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-1024x760.jpg 1024w, https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-200x148.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-768x570.jpg 768w, https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-1536x1140.jpg 1536w, https://www.wp-tr.org/wp-content/uploads/2024/06/sayilarla-guzel-hosting-02-2048x1520.jpg 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Güzel Hosting, 2008 yılından bu yana &#8220;<strong>en uygun ücretlerle en iyi hizmeti sunabilmek</strong>&#8221; anlayışıyla faaliyet göstermektedir. Bu anlayış sayesinde sektörde 16 yılı aşkın süredir öncü bir konuma gelmiş bulunmaktadır. Müşterilerinin iş ve web sitelerinin öneminin bilincinde olarak, 365 gün 7/24 çalışmakta ve her soruna en hızlı şekilde müdahale etmekteler. Paylaşımlı sunucuların sürekli takibi yapılarak olası sorunlara en kısa sürede müdahale edebiliyorlar, böylece %99 uptime garantisini aşan bir hizmet sunmaktalar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">2024 Haziran verilerine göre Güzel Hosting&#8217;in, toplam <strong>150.853 aktif müşteri</strong> hesabı bulunmakta olup, VPS/VDS ve sunucu hizmetleri hariç yaklaşık <strong>192.859 web sitesi</strong> sunucularında barınmakta. Ayrıca, verilen alan adı bayilikleri hariç, <strong>97.983 aktif alan adı</strong> kayıtlıdır. <a href=\"https://www.guzel.net.tr/kurumsal-email.php\">Kurumsal mail</a> hizmetlerinde ise toplam <strong>35.491 posta kutusu</strong>nda <strong>92.000.478 adet e-posta</strong> saklanmaktadır. Bu veriler, Güzel Hosting’in sektördeki büyüklüğünü ve müşteri memnuniyetine verdiği önemi göstermektedir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Güzel Hosting, Türkiye’nin yerli sermayeye sahip en çok web sitesi barındıran <a href=\"https://www.guzel.net.tr/hosting.php\">web hosting</a> şirketi olmanın sorumluluğu ile sektörün lideri olmaya devam ediyor. Her gün altyapı güçlendirmeleri ve geliştirmeler yaparak, müşterilerine daha iyi hizmet sunmak için aralıksız çalışıyorlar.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20526\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"Katılımcı gününün ardından\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"https://www.wp-tr.org/katilimci-gununun-ardindan/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 14 Jun 2024 08:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20521\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:490:\"Her yıl, WordCamp Avrupa başlamadan önce (ya da bazen sonra) bir günlük katılımcı günü etkinliği düzenleniyor. WordPress&#8217;e gönül vermiş kişiler bir araya gelerek, bir günlük süre içerisinde WordPress&#8217;e olabildiğince katkıda bulunmaya çalışıyorlar. Bu yıl katılımcı gününe katılım o kadar fazlaydı ki, katılımcı sayısını sınırlandırmak ve bilet ile katılım yaptırmak durumunda kalındı. 700&#8217;ü aşkın gönüllü 24 [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3660:\"\n<p class=\"wp-block-paragraph\">Her yıl, WordCamp Avrupa başlamadan önce (ya da bazen sonra) bir günlük katılımcı günü etkinliği düzenleniyor. WordPress&#8217;e gönül vermiş kişiler bir araya gelerek, bir günlük süre içerisinde WordPress&#8217;e olabildiğince katkıda bulunmaya çalışıyorlar.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-scaled.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-1024x683.jpg\" alt=\"\" class=\"wp-image-20522\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-1024x683.jpg 1024w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-200x133.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-768x512.jpg 768w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-1536x1024.jpg 1536w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-01-2048x1365.jpg 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Bu yıl katılımcı gününe katılım o kadar fazlaydı ki, katılımcı sayısını sınırlandırmak ve bilet ile katılım yaptırmak durumunda kalındı. 700&#8217;ü aşkın gönüllü 24 farklı grupta tüm gün boyunca WordPress&#8217;e katkı sağladılar.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Gruplar</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Bu yılki gruplar aşağıdaki gibiydi;</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>WordPress Coding Standards (WordPress Kodlama Standartları)</li>\n\n\n\n<li>Core (Çekirdek)</li>\n\n\n\n<li>Design (Tasarım)</li>\n\n\n\n<li>Mobile (Mobil)</li>\n\n\n\n<li>Accessibility (Erişilebilirlik)</li>\n\n\n\n<li>Polyglots (Çok Dillilik)</li>\n\n\n\n<li>Support (Destek)</li>\n\n\n\n<li>Documentation (Dokümantasyon)</li>\n\n\n\n<li>Themes (Temalar)</li>\n\n\n\n<li>Plugins (Eklentiler)</li>\n\n\n\n<li>Community (Topluluk)</li>\n\n\n\n<li>Meta (Meta)</li>\n\n\n\n<li>Training (Eğitim)</li>\n\n\n\n<li>Test (Test)</li>\n\n\n\n<li>TV (TV)</li>\n\n\n\n<li>Marketing (Pazarlama)</li>\n\n\n\n<li>CLI (Komut Satırı Arayüzü)</li>\n\n\n\n<li>Hosting (Hosting)</li>\n\n\n\n<li>Tide (Tide)</li>\n\n\n\n<li>Openverse (Openverse)</li>\n\n\n\n<li>Photos (Fotoğraflar)</li>\n\n\n\n<li>Core Performance (Çekirdek Performansı)</li>\n\n\n\n<li>Sustainability (Sürdürülebilirlik)</li>\n\n\n\n<li>Diversity, Equity, Inclusion, and Belonging (DEIB) Working Group (Çeşitlilik, Eşitlik, Kapsayıcılık ve Aidiyet Çalışma Grubu)</li>\n</ul>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"730\" src=\"https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02-1024x730.jpg\" alt=\"\" class=\"wp-image-20524\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02-1024x730.jpg 1024w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02-200x143.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02-768x548.jpg 768w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02-1536x1095.jpg 1536w, https://www.wp-tr.org/wp-content/uploads/2024/06/katilimci-gunu-02.jpg 2048w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Uzaktan katılımın da sağlandığı günün sonunda bir çok grup harika işler başardılar. Biz de çeviri konusunda çalışarak günün sonunda bir çok farklı tema ve eklentisinin çevirisini yaparak, 6.000&#8217;in üzerinde dizenin çevirisini tamamladık.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20521\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sayılarla WordCamp Avrupa 2023\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://www.wp-tr.org/sayilarla-wordcamp-avrupa-2023/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 12 Jun 2024 12:35:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2023\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20518\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:504:\"WordCamp Avrupa 2023, 94 ülkeden 2.545 WordPress meraklısını Atina&#8217;da bir araya getiren, büyük bir WordPress etkinliğiydi. Özellikle pandemi sonrası fiziksel etkinliklerin tekrar hız kazandığı bir dönemde, küresel erişimini ortaya serecek nitelikle görkemli bir etkinlik oldu. WordCamp Avrupa ilham verici ve bilgilendirici bir etkinlik olduğunu kanıtlarcasına WordPress topluluğunu güçlendirirken, trendler, yeni yaklaşımlar ve gelecekteki değişikliklere kapı [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:4321:\"\n<p class=\"wp-block-paragraph\">WordCamp Avrupa 2023, 94 ülkeden 2.545 WordPress meraklısını Atina&#8217;da bir araya getiren, büyük bir WordPress etkinliğiydi. Özellikle pandemi sonrası fiziksel etkinliklerin tekrar hız kazandığı bir dönemde, küresel erişimini ortaya serecek nitelikle görkemli bir etkinlik oldu.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Avrupa ilham verici ve bilgilendirici bir etkinlik olduğunu kanıtlarcasına WordPress topluluğunu güçlendirirken, trendler, yeni yaklaşımlar ve gelecekteki değişikliklere kapı araladı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tamamen şeffaf bir etkinlik oluşturma mottosunu koruyarak, verileri inceledik ve bilmek istediğiniz sayıları sizler için derledik.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Katılımcılar</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>2.545 kişi etkinliğe katıldı</li>\n\n\n\n<li>90 ülke temsil edildi</li>\n\n\n\n<li>1.400 kişi ilk kez katıldı</li>\n\n\n\n<li>110 mikro sponsorluk</li>\n\n\n\n<li>222 vize mektubu oluşturuldu</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Gönüllüler</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>142 gönüllü</li>\n\n\n\n<li>40 ülke temsil edildi</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Organizatörler</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>98 organizatör</li>\n\n\n\n<li>21 ülke temsil edildi</li>\n\n\n\n<li>11 farklı takım</li>\n\n\n\n<li>13 takım lideri</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Medya</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>10 medya ortağı</li>\n\n\n\n<li>11 medya sponsoru</li>\n\n\n\n<li>Sosyal medya paylaşımlarından 23,2 milyon kişiye ulaşıldı</li>\n\n\n\n<li>14.000 etkileşim</li>\n\n\n\n<li>2.000&#8217;den fazla Twitter bahsetmesi</li>\n\n\n\n<li>4.000&#8217;den fazla sosyal medya içerik paylaşımı</li>\n\n\n\n<li>12.200&#8217;den fazla beğeni</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Fotoğraf</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Etkinlik sırasında 28.000 fotoğraf çekildi (tekrar eden fotoğraflar çıkartıldığında) ve 4.900&#8217;u Flickr hesabımıza yüklendi!</li>\n\n\n\n<li>15 fotoğrafçı</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Konuşmacılar</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>102 konuşmacı</li>\n\n\n\n<li>29 ülke temsil edildi</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Temsil edilen ülkeler</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Bangladeş 1</li>\n\n\n\n<li>Brezilya 1</li>\n\n\n\n<li>Hırvatistan 1</li>\n\n\n\n<li>Estonya 1</li>\n\n\n\n<li>Yunanistan 1</li>\n\n\n\n<li>Japonya 1</li>\n\n\n\n<li>Litvanya 1</li>\n\n\n\n<li>Polonya 1</li>\n\n\n\n<li>Portekiz 1</li>\n\n\n\n<li>Slovenya 1</li>\n\n\n\n<li>Vietnam 1</li>\n\n\n\n<li>Zimbabve 1</li>\n\n\n\n<li>Avustralya 2</li>\n\n\n\n<li>Kanada 2</li>\n\n\n\n<li>Kosta Rika 2</li>\n\n\n\n<li>İsveç 2</li>\n\n\n\n<li>İsviçre 2</li>\n\n\n\n<li>Hindistan 3</li>\n\n\n\n<li>İtalya 3</li>\n\n\n\n<li>Sırbistan 3</li>\n\n\n\n<li>Güney Afrika 3</li>\n\n\n\n<li>İsrail 4</li>\n\n\n\n<li>Bulgaristan 6</li>\n\n\n\n<li>Almanya 8</li>\n\n\n\n<li>Hollanda 9</li>\n\n\n\n<li>Birleşik Krallık 9</li>\n\n\n\n<li>İspanya 11</li>\n\n\n\n<li>ABD 21</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Sponsorlar</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>64 sponsor</li>\n\n\n\n<li>Porto&#8217;da sponsor olan ve Atina&#8217;da da sponsorlar %56,25 oranına sahipken, sponsorların %43,75 kadarı bu sene WordCamp Avrupa&#8217;ya ilk kez sponsor oldular.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Katılımcı Günü</h2>\n\n\n\n<p class=\"wp-block-paragraph\">658 Katılımcı<br>144 Yeni katılımcı<br>23 Takım</p>\n\n\n\n<h2 class=\"wp-block-heading\">Sonuç</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Rakamlar bir araya geliyor ve sayıları oluşturuyorlar. Etkileyici bir hikaye anlatıyor olabilirler, ancak olayı dikkat çekici kılan insanlardır. Her sayının arkasında anlatacak bir WordPress hikayesi olan bir kişi yatar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Gerçek sihir, insanlar birbirleriyle bağlantı kurduğunda, paylaştığında ve etkileşime geçtiğinde gerçekleşir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Avrupa 2023&#8217;ün unutulmaz bir an olmasına yardımcı olan herkese teşekkürler.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Bu yazı Wordcamp Avrupa 2023 sitesinde yayınlanmış olan <a href=\"https://europe.wordcamp.org/2023/wceu-2023-in-numbers/\">WCEU 2023 in Numbers</a> yazısının çevirisidir.</p>\n</blockquote>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20518\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"https://www.wp-tr.org/wordcamp-avrupa-2024/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 12 Jun 2024 07:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20514\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:493:\"WordCamp Avrupa, gündelik kullanıcılardan çekirdek geliştiricilere kadar WordPress meraklılarının bir araya geldiği, gayri resmi ve topluluk tarafından organize edilen bir buluşmadır. Farklı ülke ve şehirlerde düzenlenen etkinlik her sene 3.000 civarında katılımcıyla üç gün sürüyor. WordCamp Avrupa&#8217;da ne yapılır? WordCamp Avrupa&#8217;da çok fazla etkinlik gerçekleşir ve bu yılki etkinlik de geçtiğimiz yıllardan farklı olmayacaktır. Üç [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3224:\"\n<p class=\"wp-block-paragraph\">WordCamp Avrupa, gündelik kullanıcılardan çekirdek geliştiricilere kadar WordPress meraklılarının bir araya geldiği, gayri resmi ve topluluk tarafından organize edilen bir buluşmadır. Farklı ülke ve şehirlerde düzenlenen etkinlik her sene 3.000 civarında katılımcıyla üç gün sürüyor.</p>\n\n\n\n<h2 class=\"wp-block-heading\">WordCamp Avrupa&#8217;da ne yapılır?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Avrupa&#8217;da çok fazla etkinlik gerçekleşir ve bu yılki etkinlik de geçtiğimiz yıllardan farklı olmayacaktır. Üç gün boyunca gerçekleşecek birçok konuşma, birçok uygulamalı oturum ve atölye çalışması ile katılımcılar kendilerini eğitme şansına ve diğer katılımcılarla ağ kurma fırsatına sahip olacaklar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Son yıllarda etkinliğin hayli büyümesiyle beraber konuşmalar birden çok sahnede yer almaya başladılar. Bu yıl üç ayrı sahnede bir çok konuşmacı, konuşmalarını sunacaklar. Programı resmi siteden <a href=\"https://europe.wordcamp.org/2024/schedule/\" target=\"_blank\" rel=\"noreferrer noopener\">inceleyebilirsiniz</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sahnelere ek olarak, fuaye alanında stand açmış olan büyük şirketlerden küçük niş şirketlere kadar bir çok sponsor da renkli anlar oluşturabiliyor. Bu şirketlerin çalışanlarıyla tanışabilir, ürün tanıtımlarına katılabilir ve sohbet edebilirsiniz. Eğlenceli mini oyunlar ve hediyeler de cabası.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Diğer katılımcılarla sohbet ederek WordPress topluluğunun diğer üyelerini tanıma fırsatını yakalamak belki de bu etkinliğin en önemli konularından biri. Twitter&#8217;da takip ettiğiniz biriyle, kullanıcı gruplarında tanıştığınız biriyle veya önceki bir WordCamp&#8217;ten tanıdık bir yüzle karşılaşabilirsiniz. WCEU, eski ve yeni arkadaşlarla tanışmak için harika bir yer.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Katkıda Bulunma</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Konferansa ek olarak, ilk gün <a href=\"https://europe.wordcamp.org/2024/contributor-day/\" target=\"_blank\" rel=\"noreferrer noopener\">Katılımcı Günü</a> adıyla hem yeni, hem de deneyimli topluluk üyelerinin bir araya gelip WordPress projesine katılmanın farklı yollarını öğrendiği özel bir gün düzenleniyor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Katılımcı Günü herkese açık olmasına rağmen, yoğun talep nedeniyle bu yıl kayıt olanlarla sınırlandırıldı. Yine de 700 civarında WordPress sever katılımcı günü için kaydolmuş durumda!</p>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress Türkiye olarak ne yapıyoruz?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Geçmiş yıllarda olduğu gibi, bu yıl da WordCamp Avrupa etkinliği ile ilgili haberleri size taşımaya çalışıyoruz. Bu yıl WordPress Türkiye ekibinden Emre Erkan, <a href=\"https://www.guzel.net.tr/\" target=\"_blank\" rel=\"noreferrer noopener\">Güzel Hosting</a> sponsorluğunda etkinliğe katılacak ve izlenimlerini paylaşacak. Blog yazılarımızı ve sosyal medya hesaplarımızı takip etmeyi unutmayın. Sponsorumuzun küçük sürprizleri olacak!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20514\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"WordCamp Avrupa’da neler oluyor?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://www.wp-tr.org/wordcamp-avrupada-neler-oluyor/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 10 Jun 2023 07:05:19 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2023\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20449\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:448:\"Bu yıl Atina&#8217;da düzenlenen WordCamp Avrupa etkinliği Atina&#8217;nın en büyük konferans merkezi olan Megaron Atina Uluslararası Konferans Merkezinde (Megaron Athens International Conference Centre &#8211; MAICC) düzenleniyor. Şehrin merkezinde yer alan konferans merkezi toplamda 143.000 metrekarelik bir alana sahip, 18 adet toplantı alanı ile birlikte geniş bir sergi ve fuaye alanıyla da hizmet veriyor. Sadece sergi [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5321:\"\n<p class=\"wp-block-paragraph\">Bu yıl Atina&#8217;da düzenlenen WordCamp Avrupa etkinliği Atina&#8217;nın en büyük konferans merkezi olan Megaron Atina Uluslararası Konferans Merkezinde (Megaron Athens International Conference Centre &#8211; MAICC) düzenleniyor. Şehrin merkezinde yer alan konferans merkezi toplamda 143.000 metrekarelik bir alana sahip, 18 adet toplantı alanı ile birlikte geniş bir sergi ve fuaye alanıyla da hizmet veriyor. Sadece sergi ve fuaye alanları toplamda 12.000 metrekarelik bir alana sahip. WordCamp Avrupa etkinliği de bu geniş alanı en güzel şekilde kullanıyor.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2023/06/maicc.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://www.wp-tr.org/wp-content/uploads/2023/06/maicc-1024x768.jpg\" alt=\"\" class=\"wp-image-20450\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2023/06/maicc-1024x768.jpg 1024w, https://www.wp-tr.org/wp-content/uploads/2023/06/maicc-200x150.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2023/06/maicc-768x576.jpg 768w, https://www.wp-tr.org/wp-content/uploads/2023/06/maicc.jpg 1434w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Etkinliğe Avrupa&#8217;nın bir çok ülkesinden 1.500&#8217;ün üzerinde katılımcı katılıyor. Üç konferans salonunda konuşmalar devam ederken iki konferans salonu da atölye çalışmaları için ayrılmış durumda. Ayrıca bir salon da aile olarak gelmiş katılımcıların çocukları için ayrılmış durumda ve mini bir WordCamp de burada devam ediyor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Konferans salonlarının hemen dışında, fuaye alanında ve koridorlarda etkinliğe sponsor olan firmaların standları yer alıyor. Oldukça fazla sayıda sponsor olduğu için bu alanlar bir pazar alanı havası taşıyor.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2023/06/fuaye.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1000\" height=\"563\" src=\"https://www.wp-tr.org/wp-content/uploads/2023/06/fuaye.jpg\" alt=\"\" class=\"wp-image-20451\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2023/06/fuaye.jpg 1000w, https://www.wp-tr.org/wp-content/uploads/2023/06/fuaye-200x113.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2023/06/fuaye-768x432.jpg 768w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Birçok firma, ürünlerini tanıtmak ve katılımcılarla bağ kurmak amacıyla çeşitli çekilişler ve hediyeler düzenliyor. Katılımcılar hem WordPress ekosistemini daha yakından tanıma fırsatı buluyor hem de yeni işbirlikleri için adımlar atabiliyorlar. WordCamp ekibi de etkileşimi en üst düzeyde tutabilmek, insanların daha kolay birbirleriyle iletişime geçebilmelerini sağlamak için bir oyun eklemiş. Kayıtta size dört adet kartpostal veriliyor. Dördü de birbirinin aynı. Fakat başka katılımcılarda farklı tasarıma sahip kartpostallar var. Konuşup, tanışıp kartpostal takası yapabiliyorsunuz. İletişimi başlatmak için harika bir strateji. Ayrıca kartpostal olmaları da uzaklarda yaşayan sevdiklerinize küçük bir sürpriz yapmanız için sizi tetikliyor.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2023/06/canli-yayin.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1000\" height=\"517\" src=\"https://www.wp-tr.org/wp-content/uploads/2023/06/canli-yayin.jpg\" alt=\"\" class=\"wp-image-20453\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2023/06/canli-yayin.jpg 1000w, https://www.wp-tr.org/wp-content/uploads/2023/06/canli-yayin-200x103.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2023/06/canli-yayin-768x397.jpg 768w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Her bir konferans salonunda devam eden etkinliklerin listesine <a href=\"https://europe.wordcamp.org/2023/schedule/\" target=\"_blank\" rel=\"noreferrer noopener\">buradan</a>, etkinlikleri canlı olarak seyretmek isterseniz de canlı yayın listesine buradan <a href=\"https://europe.wordcamp.org/2023/live-streaming/\" target=\"_blank\" rel=\"noreferrer noopener\">ulaşabilirsiniz</a>.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"alignright size-full\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo.webp\"><img loading=\"lazy\" decoding=\"async\" width=\"278\" height=\"47\" src=\"https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo.webp\" alt=\"\" class=\"wp-image-20442\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo.webp 278w, https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo-200x34.webp 200w\" sizes=\"auto, (max-width: 278px) 100vw, 278px\" /></a></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Etkinliğe katılım, bu bilgileri size aktarmamızı sağlayan sponsorumuz Güzel Hosting&#8217;e bir kere daha teşekkür ederiz. <a href=\"https://twitter.com/WP_Turkiye/status/1667124693382332418\" target=\"_blank\" rel=\"noreferrer noopener\">Twitter</a>&#8216;da ve Facebook&#8217;da devam eden iki ayrı çekiliş ile WP-Mini paketi kazanma fırsatı devam ediyor.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20449\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"Yeniden WordCamp Avrupa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"https://www.wp-tr.org/yeniden-wordcamp-avrupa/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 08 Jun 2023 10:12:40 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordCamp Avrupa 2023\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20445\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:458:\"Tekrar Merhaba! Ben Emre Erkan. 2005 yılından beri aktif olarak WordPress kullanıyor ve 2008 yılından beri WordPress Türkiye ekibini yönetiyorum. Türkçe paketin hazırlanması, topluluk yönetimi, etkinliklerin düzenlenmesi, WordPress.org ile iletişim gibi bir çok alanda gönüllü olarak çalışıyorum. WordCamp Avrupa 2023 bugün başlıyor. Geçen yıllarda olduğu gibi bu yıl da üç gün sürecek etkinliği WordPress Türkiye [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:8638:\"\n<figure class=\"wp-block-image size-full\"><a href=\"https://www.wp-tr.org/wp-content/uploads/2023/06/baslangic.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1000\" height=\"750\" src=\"https://www.wp-tr.org/wp-content/uploads/2023/06/baslangic.jpg\" alt=\"\" class=\"wp-image-20446\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2023/06/baslangic.jpg 1000w, https://www.wp-tr.org/wp-content/uploads/2023/06/baslangic-200x150.jpg 200w, https://www.wp-tr.org/wp-content/uploads/2023/06/baslangic-768x576.jpg 768w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Tekrar Merhaba!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Ben Emre Erkan. 2005 yılından beri aktif olarak WordPress kullanıyor ve 2008 yılından beri WordPress Türkiye ekibini yönetiyorum. Türkçe paketin hazırlanması, topluluk yönetimi, etkinliklerin düzenlenmesi, WordPress.org ile iletişim gibi bir çok alanda gönüllü olarak çalışıyorum.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Avrupa 2023 bugün başlıyor. Geçen yıllarda olduğu gibi bu yıl da üç gün sürecek etkinliği WordPress Türkiye takipçilerine aktarmak için <a rel=\"noreferrer noopener\" href=\"https://www.guzel.net.tr\" target=\"_blank\">Güzel Hosting</a> sponsorluğunda Atina&#8217;da olacağım. Blog yazıları, Facebook üzerinden canlı yayınlar ve sosyal medya paylaşımları ile elimden geldiğince etkinliği sizlere aktarmaya çalışacağım.</p>\n\n\n\n<ul class=\"wp-block-social-links is-style-default is-content-justification-center is-layout-flex wp-container-core-social-links-is-layout-fe48e5de wp-block-social-links-is-layout-flex\"><li class=\"wp-social-link wp-social-link-facebook wp-block-social-link\"><a href=\"https://www.facebook.com/WPTurkiye/\" class=\"wp-block-social-link-anchor\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" version=\"1.1\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M12 2C6.5 2 2 6.5 2 12c0 5 3.7 9.1 8.4 9.9v-7H7.9V12h2.5V9.8c0-2.5 1.5-3.9 3.8-3.9 1.1 0 2.2.2 2.2.2v2.5h-1.3c-1.2 0-1.6.8-1.6 1.6V12h2.8l-.4 2.9h-2.3v7C18.3 21.1 22 17 22 12c0-5.5-4.5-10-10-10z\"></path></svg><span class=\"wp-block-social-link-label screen-reader-text\">Facebook</span></a></li>\n\n<li class=\"wp-social-link wp-social-link-twitter wp-block-social-link\"><a href=\"https://twitter.com/WP_Turkiye\" class=\"wp-block-social-link-anchor\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" version=\"1.1\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M22.23,5.924c-0.736,0.326-1.527,0.547-2.357,0.646c0.847-0.508,1.498-1.312,1.804-2.27 c-0.793,0.47-1.671,0.812-2.606,0.996C18.324,4.498,17.257,4,16.077,4c-2.266,0-4.103,1.837-4.103,4.103 c0,0.322,0.036,0.635,0.106,0.935C8.67,8.867,5.647,7.234,3.623,4.751C3.27,5.357,3.067,6.062,3.067,6.814 c0,1.424,0.724,2.679,1.825,3.415c-0.673-0.021-1.305-0.206-1.859-0.513c0,0.017,0,0.034,0,0.052c0,1.988,1.414,3.647,3.292,4.023 c-0.344,0.094-0.707,0.144-1.081,0.144c-0.264,0-0.521-0.026-0.772-0.074c0.522,1.63,2.038,2.816,3.833,2.85 c-1.404,1.1-3.174,1.756-5.096,1.756c-0.331,0-0.658-0.019-0.979-0.057c1.816,1.164,3.973,1.843,6.29,1.843 c7.547,0,11.675-6.252,11.675-11.675c0-0.17