.5-0.5-1.002-0.808-1.594-1.038c-0.572-0.222-1.227-0.375-2.185-0.418C14.751,3.01,14.444,3,12,3L12,3z M12,7.378 c-2.552,0-4.622,2.069-4.622,4.622S9.448,16.622,12,16.622s4.622-2.069,4.622-4.622S14.552,7.378,12,7.378z M12,15 c-1.657,0-3-1.343-3-3s1.343-3,3-3s3,1.343,3,3S13.657,15,12,15z M16.804,6.116c-0.596,0-1.08,0.484-1.08,1.08 s0.484,1.08,1.08,1.08c0.596,0,1.08-0.484,1.08-1.08S17.401,6.116,16.804,6.116z\"></path></svg><span class=\"wp-block-social-link-label screen-reader-text\">Instagram</span></a></li>\n\n<li class=\"wp-social-link wp-social-link-wordpress wp-block-social-link\"><a href=\"https://tr.wordpress.org\" class=\"wp-block-social-link-anchor\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" version=\"1.1\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M12.158,12.786L9.46,20.625c0.806,0.237,1.657,0.366,2.54,0.366c1.047,0,2.051-0.181,2.986-0.51 c-0.024-0.038-0.046-0.079-0.065-0.124L12.158,12.786z M3.009,12c0,3.559,2.068,6.634,5.067,8.092L3.788,8.341 C3.289,9.459,3.009,10.696,3.009,12z M18.069,11.546c0-1.112-0.399-1.881-0.741-2.48c-0.456-0.741-0.883-1.368-0.883-2.109 c0-0.826,0.627-1.596,1.51-1.596c0.04,0,0.078,0.005,0.116,0.007C16.472,3.904,14.34,3.009,12,3.009 c-3.141,0-5.904,1.612-7.512,4.052c0.211,0.007,0.41,0.011,0.579,0.011c0.94,0,2.396-0.114,2.396-0.114 C7.947,6.93,8.004,7.642,7.52,7.699c0,0-0.487,0.057-1.029,0.085l3.274,9.739l1.968-5.901l-1.401-3.838 C9.848,7.756,9.389,7.699,9.389,7.699C8.904,7.67,8.961,6.93,9.446,6.958c0,0,1.484,0.114,2.368,0.114 c0.94,0,2.397-0.114,2.397-0.114c0.485-0.028,0.542,0.684,0.057,0.741c0,0-0.488,0.057-1.029,0.085l3.249,9.665l0.897-2.996 C17.841,13.284,18.069,12.316,18.069,11.546z M19.889,7.686c0.039,0.286,0.06,0.593,0.06,0.924c0,0.912-0.171,1.938-0.684,3.22 l-2.746,7.94c2.673-1.558,4.47-4.454,4.47-7.771C20.991,10.436,20.591,8.967,19.889,7.686z M12,22C6.486,22,2,17.514,2,12 C2,6.486,6.486,2,12,2c5.514,0,10,4.486,10,10C22,17.514,17.514,22,12,22z\"></path></svg><span class=\"wp-block-social-link-label screen-reader-text\">WordPress</span></a></li></ul>\n\n\n\n<h2 class=\"wp-block-heading\">Sponsorumuzu tanıyalım</h2>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"alignright size-full\"><a href=\"https://www.guzel.net.tr\"><img loading=\"lazy\" decoding=\"async\" width=\"278\" height=\"47\" src=\"https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo.webp\" alt=\"\" class=\"wp-image-20442\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo.webp 278w, https://www.wp-tr.org/wp-content/uploads/2023/06/guzelhosting-logo-200x34.webp 200w\" sizes=\"auto, (max-width: 278px) 100vw, 278px\" /></a></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\"><strong>Güzel Hosting</strong>, 2008&#8217;den beri en uygun ücretlerle en iyi hizmeti sunma anlayışıyla sektörde öncü bir şirket olarak faaliyet göstermektedir. Müşterilerinin işleri ve web sitelerinin ne kadar önemli olduğunun farkında olan Güzel Hosting, 365 gün 24 saat çalışarak her soruna en hızlı şekilde müdahale etmekte ve %99 uptime garantisini aşan bir oranda çalışmayı sağlamaktadır. Şeffaf ve özverili yaklaşımları, müşterilerin güvenini kazanmada en önemli faktörlerdir. Güzel Hosting, sürekli olarak geleceğe yatırım yaparak altyapısını güçlendirmekte ve müşterilerine daha iyi hizmet sunabilmek için kendilerine özgü sistemler ve yazılımlar geliştirmektedir. Her geçen gün ekibini de büyüterek sürekli gelişmeyi hedeflemektedir.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20445\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:63:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n\n\n\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:22:\"WordPress Türkçe 5.5\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"https://www.wp-tr.org/wordpress-turkce-5-5/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 12 Aug 2020 09:43:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:14:\"Güncellemeler\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Haberler\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20331\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:518:\"İşte burada! Billy Eckstine anısına “Eckstine” olarak isimlendirilmiş bu son ve harika WordPress sürümünü indirebilir ya da panelinizden güncelleme yapabilirsiniz. Hız Geç yüklenen görseller sayesinde yazı ve sayfalarınız daha hızlı hissedilecek. Görseller hikayelerinizde harika bir etki yaratabiliyor fakat bazen sitenizi yavaşlatabiliyor. WordPress 5.5 ile görseller tarayıcının görünür alanına kaydırıldıklarında görünür oluyorlar. Bu olayın teknik karşılığı [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"enclosure\";a:3:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:3:\"url\";s:48:\"https://s.w.org/images/core/5.5/auto-updates.mp4\";s:6:\"length\";s:6:\"238264\";s:4:\"type\";s:9:\"video/mp4\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:3:\"url\";s:50:\"https://s.w.org/images/core/5.5/block-patterns.mp4\";s:6:\"length\";s:7:\"3518792\";s:4:\"type\";s:9:\"video/mp4\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:3:\"url\";s:56:\"https://s.w.org/images/core/5.5/inline-image-editing.mp4\";s:6:\"length\";s:7:\"3145140\";s:4:\"type\";s:9:\"video/mp4\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:14826:\"\n<p class=\"wp-block-paragraph\">İşte burada! Billy Eckstine anısına “Eckstine” olarak isimlendirilmiş bu son ve harika WordPress sürümünü <a rel=\"noreferrer noopener\" href=\"https://tr.wordpress.org/download/\" target=\"_blank\">indirebilir</a> ya da panelinizden güncelleme yapabilirsiniz.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2020/08/Billy_duotone-1000px_quiche-sans-top.png\" alt=\"\" class=\"wp-image-8930\"/></figure>\n\n\n\n<div class=\"wp-block-cover has-background-dim\" style=\"background-color:#f2edd4;min-height:300px;aspect-ratio:unset;\"><div class=\"wp-block-cover__inner-container is-layout-flow wp-block-cover-is-layout-flow\">\n<p class=\"has-text-align-center has-black-color has-text-color has-background has-large-font-size wp-block-paragraph\" style=\"background-color:#f2edd4\">WordPress 5.5 karşınızda.</p>\n\n\n\n<h3 class=\"has-text-align-center has-black-color has-text-color wp-block-heading\">WordPress 5.5 sitenizin üç ana alanda yeni güçlere kavuşmasını sağlayacak:<br>hız, arama ve güvenlik..</h3>\n</div></div>\n\n\n\n<div class=\"wp-block-columns has-white-background-color has-background is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:96%\">\n<h2 class=\"wp-block-heading\">Hız</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Geç yüklenen görseller sayesinde yazı ve sayfalarınız daha hızlı hissedilecek.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Görseller hikayelerinizde harika bir etki yaratabiliyor fakat bazen sitenizi yavaşlatabiliyor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 5.5 ile görseller tarayıcının görünür alanına kaydırıldıklarında görünür oluyorlar. Bu olayın teknik karşılığı &#8216;geç yükleme&#8217;.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mobilde, geç yükleme diğer cihazlar için yüklenmesi planlanan dosyalardan da koruma sağlar. Bu da okuyucularınızın veriye daha az ücret ödemesine — ve daha az pil tüketimine yol açar.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Arama</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Yeni site haritanıza merhaba deyin.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress siteleri arama motorlarıyla uyumlu çalışır.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Artık varsayılan olarak WordPress 5.5, arama motorlarının yayına girdiğiniz andan itibaren en önemli sayfalarınızı keşfetmesine yardımcı olan bir XML site haritası içerir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Böylece daha fazla kişi sitenizi daha erken bulur, bu sayede onları meşgul etmek, elde tutmak ve abonelere, müşterilere veya başarı tanımınıza uyan her şeye dönüştürmek için daha fazla zaman tanır.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n</div>\n\n\n\n<div class=\"wp-block-columns has-background is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\" style=\"background-color:#ebcd3d\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:96%\">\n<h2 class=\"wp-block-heading\">Güvenlik</h2>\n\n\n\n<figure class=\"wp-block-video\"><video controls src=\"https://s.w.org/images/core/5.5/auto-updates.mp4\"></video><figcaption>Artık eklenti ve temalarınızı otomatik güncelleyebileceksiniz. Hem de bu işlemi her zaman kullandığınız alışık olduğunuz ekranlar üzerinden ayarlayacaksınız.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Eklentiler ve temalar için otomatik güncellemeler</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Artık, WordPress yönetim ekranından, eklentileri ve temaları otomatik olarak güncellenecek veya güncellenmeyecek şekilde ayarlayabilirsiniz. Böylece her zaman sitenizin mevcut en son kodu çalıştırdığını bilirsiniz.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ayrıca her bir eklenti ya da tema için otomatik güncellemeleri açıp, kapatabilirsiniz — hepsi hali hazırda kullandığınız ekranlara eklendi.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>ZIP dosyaları yükleyerek güncelleme</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Eğer eklenti ve temaları kendiniz yüklemeyi seviyorsanız, artık bu da kolay — sadece ZIP dosyasını yükleyin.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n</div>\n\n\n\n<div class=\"wp-block-columns has-background is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\" style=\"background-color:#f2edd4\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:96%\">\n<h2 class=\"wp-block-heading\">Blok düzenleyicide öne çıkanlar</h2>\n\n\n\n<p class=\"wp-block-paragraph\">En son WordPress sürümü bir kez daha blok düzenleyici için heyecan verici yeni özelliklerin uzun bir listesini içeriyor. Örneğin:</p>\n\n\n\n<figure class=\"wp-block-video\"><video controls src=\"https://s.w.org/images/core/5.5/block-patterns.mp4\"></video></figure>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading\">Blok desenleri</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Yeni blok desenleri, hikayenize uyacak şekilde karıştırıp eşleştirebileceğiniz metin ve ortam kombinasyonlarını kullanarak karmaşık, güzel düzenler oluşturmayı basit ve eğlenceli hale getirir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ayrıca blok desenlerini geniş bir eklenti ve tema seçkisinde bulabilirsiniz, ki zaman içinde daha çoğu da gelecek. İstediğinizi tek bir yerden seçin — tıklayın ve ilerleyin!</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading\">Yeni blok dizini</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Artık ihtiyacınız olan bloğu bulmak her zamankinden kolay. Yeni blok dizini blok düzenleyici içinde gömülü durumda, böylece düzenleyiciyi terk etmeden sitenize yeni bloklar ekleyebileceksiniz.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Satır içi görsel düzenleme</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Fotoğraflarınızı doğrudan görsel bloğundan kırpın, döndürün ve yakınlaştırın. Görsellere çok fazla zaman harcıyorsanız, bu size zaman kazandırabilir!</p>\n</div>\n</div>\n\n\n\n<figure class=\"wp-block-video\"><video controls src=\"https://s.w.org/images/core/5.5/inline-image-editing.mp4\"></video></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Ve çok daha fazlası.</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Yukardakiler yüklemiş olduğunuz yeni blok düzenleyici özelliklerinin küçük bir parçası. Blok düzenleyiciyi açın ve keyfini çıkarın!</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n</div>\n\n\n\n<div class=\"wp-block-columns has-white-background-color has-background is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:96%\">\n<h2 class=\"wp-block-heading\">Erişilebilirlik</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Her dağıtım erişilebilir yayımlama deneyimine katkıda bulunuyor, ve bu WordPress 5.5 içinde geçerliliğini koruyor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Artık ortam ekranlarında ve modal pencerelerde bir satır metni seçmek yerine tek bir tuş ile bağlantıları kopyalayabilirsiniz.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Meta kutularını tuş takımı ile de taşıyabilirsiniz, ve görsel düzenleyici içindeki yönergeleri size okuyabileceği için yardımcı cihazınız ile WordPress içinde görselleri düzenleyebilirsiniz.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n</div>\n\n\n\n<div class=\"wp-block-columns has-black-color has-text-color has-background is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\" style=\"background-color:#ebcd3d\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:96%\">\n<h2 class=\"wp-block-heading\">Geliştiriciler için</h2>\n\n\n\n<p class=\"wp-block-paragraph\">5.5 ayrıca geliştiriciler için büyük bit dğeişiklik kutusu getiriyor.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading\">REST API içinde sunucu taraflı kayıtlı bloklar</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Blok tipi uç noktalarının eklenmesi demek, JavaScript uygulamalarının (blok düzenleyici gibi) sunucuda kayıtlı herhangi bir blok ile ilgili tanımları alabilmesini sağlıyor.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Ortamları tanımlama</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress artık sitenin ortam tipine ait standardize edilmiş bir tanıma (test, canlı vb.) sahip. <code>wp_get_environment_type()</code> ile bu tanımı edinin ve sadece gerekli kodu çalıştırın.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Panel simgeleri</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Panel simgeleri 5.5 ile beraber son bir güncelleme aldı. 26 simge ve 29 blok düzenleyici simgesi eklendi.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Şablon dosyalarına veri aktarma</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Şablon yükleme işlevleri (<code>get_header()</code>, <code>get_template_part()</code> vb.) artık yeni bir $args argümanına sahip. Böylece o şablonlara dizi olarak tonla veri aktarabilirsiniz. .</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading\">Geliştiriciler için daha fazla değişiklik</h3>\n\n\n\n<ul class=\"wp-block-list\"><li>PHPMailer kütüphanesi büyük bir güncelleme aldı, 5.2.27 sürümünden 6.1.6 sürümüne geçti.</li><li>Aertık <code>redirect_guess_404_permalink()</code> için çok daha incelikli bir kontrole sahipsiniz.</li><li>PHP OPcache kullanan siteler daha güvenilir önbellek geçersizleştirme sonuçları alacaklar, bu da güncellemeler sırasında kullanılacak yeni <code>wp_opcache_invalidate()</code> işlevi sayesinde (eklentiler ve temalar dahil). </li><li>Kategori sınıflandırması ile ilişkilendirilmiş özel yazı tipleri artık desteklenen varsayılan terime dahil olabilir.</li><li><code>register_taxonomy()</code> içindeki özel sınıflandırmalar için varsayılan terimler artık belirtilebiliyor.</li><li>REST API artık resmi olarak <code>register_meta()</code> üzerinden varsayılan meta verileri için değerler belirlenebilmesini destekliyor.</li><li>Şu tümleşik paketlenmiş kütüphanelerin güncellenmiş sürümlerini bulacaksınız: SimplePie, Twemoji, Masonry, imagesLoaded, getID3, Moment.js, ve clipboard.js.</li></ul>\n</div>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n</div>\n\n\n\n<div class=\"wp-block-columns has-white-background-color has-background is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:96%\">\n<h2 class=\"wp-block-heading\">Ekip</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Bu sürüme liderlik edenler: <a rel=\"noreferrer noopener\" href=\"http://ma.tt/\" target=\"_blank\">Matt Mullenweg</a>,&nbsp;<a rel=\"noreferrer noopener\" href=\"https://profiles.wordpress.org/whyisjake\" target=\"_blank\">Jake Spurlock,</a> ve <a rel=\"noreferrer noopener\" href=\"https://dream-encode.com/blog/\" target=\"_blank\">David Baumwald</a>. Ayrıca kendilerine aşağıdaki dağıtım ekibi de büyük bir coşkuyla destek verdiler:</p>\n\n\n\n<ul class=\"wp-block-list\"><li><strong>Düzenleyici teknolojisi</strong> Ella Van Durpe (@ellatrix)</li><li><strong>Düzenleyici tasarımı</strong>: Michael Arestad (@michael-arestad)</li><li><strong>Çekirdek teknolojisi</strong>: Sergey Biryukov (@sergeybiryukov)</li><li><strong>Ortam teknolojisi: </strong>Andrew Ozz (@azaozz)</li><li><strong>Erişilebilirlik teknolojisi</strong>: JB Audras (@audrasjb)</li><li><strong>Belgeler koordinatörü</strong>:&nbsp;Justin Ahinon (@justinahinon)</li><li><strong>Pazarlama/İletişim koordinatörü</strong>: Mary Baum (@marybaum)</li></ul>\n\n\n\n<p class=\"wp-block-paragraph\">Ayrıca yukardaki ekibe <strong>805 kişilik gönüllü kaıtılımcıları</strong> da eklememiz lazım, ki bu katılımcılar  <strong><a rel=\"noreferrer noopener\" href=\"https://core.trac.wordpress.org/milestone/5.5\" target=\"_blank\">523</a>&#8216;den fazla bildirimi Trac üzerinden</strong> ve <strong>1660&#8217;den fazla çekme isteğini GitHub üzerinden</strong> yaparak katkı sağladılar.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/support/\">Destek forumlarında</a> gönüllü olarak katkıda bulunan tüm gönüllülere teşekkürler. Dünyanın her yerinden insanların sorularına cevap veriyorlar. İstek WordPress ile ilk kez tanışmış olun, ister uzun zamandır çözemediğiniz bir problem olsun&#8230; Bu dağıtımlar onlar sayesinde çok daha başarılı!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Son olarak, WordPress 5.5 sürümünün 50&#8217;den fazla dilde kullanıcılara ulaşmasını sağlayan çevirmenlere de büyük bir teşekkür. Bu yazı yazılırken daha bir çok dil de kullanıma hazır hale getiriliyordu.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Eğer daha fazlasını öğrenmek ve WordPress&#8217;e katkıda bulunmak isterseniz <a href=\"https://make.wordpress.org/\">Make WordPress</a> ya da <a href=\"https://make.wordpress.org/core/\">çekirdek geliştirici blog</a>unu ziyaret edebilirsiniz.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:2%\"></div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20331\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:66:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"WordPress Türkçe 4.9.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"https://www.wp-tr.org/wordpress-turkce-4-9-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 07 Feb 2018 10:24:34 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:14:\"Güncellemeler\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:5:\"4.9.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:18:\"WordPress Türkçe\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:24:\"WordPress Türkçe 4.9.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20207\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:481:\"Merhaba arkadaşlar, WordPress Türkçe 4.9.4 şu an indirilebilir durumda. 4.9.3 sürümünde ortaya çıkan bir hata nedeniyle WordPress otomatik güncelleme sistemi çalışmaz duruma geldi ve bunun için 4.9.4 sürümü çıkartıldı. Ne var ki bir önceki sürümü etkileyen bu hata nedeniyle siteniz otomatik olarak 4.9.4 sürümüne güncellenemeyecektir. Sitenizin yönetim panelinde Başlangıç &#62; Güncellemeler bölümünden 4.9.4 sürümüne güncelleme [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2119:\"<p><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter size-full wp-image-20208\" src=\"https://www.wp-tr.org/wp-content/uploads/2018/02/wordpress_4_9_4_site.png\" alt=\"\" width=\"670\" height=\"206\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2018/02/wordpress_4_9_4_site.png 670w, https://www.wp-tr.org/wp-content/uploads/2018/02/wordpress_4_9_4_site-200x61.png 200w\" sizes=\"auto, (max-width: 670px) 100vw, 670px\" /></p>\n<p>Merhaba arkadaşlar,</p>\n<p><a href=\"http://tr.wordpress.org/\"><img decoding=\"async\" src=\"/static/img/wp-indir-son.jpg\" alt=\"WordPress Türkiye indir\" align=\"left\" /></a>WordPress Türkçe 4.9.4 şu an <a href=\"http://tr.wordpress.org/\">indir</a>ilebilir durumda.</p>\n<p>4.9.3 sürümünde ortaya çıkan bir hata nedeniyle WordPress otomatik güncelleme sistemi çalışmaz duruma geldi ve bunun için 4.9.4 sürümü çıkartıldı. Ne var ki bir önceki sürümü etkileyen bu hata nedeniyle siteniz otomatik olarak 4.9.4 sürümüne güncellenemeyecektir. Sitenizin yönetim panelinde <strong>Başlangıç</strong> &gt; <strong>Güncellemeler</strong> bölümünden 4.9.4 sürümüne güncelleme yapabilirsiniz.</p>\n<h2>Son olarak</h2>\n<p>WordPress.org üzerindeki resmi 4.9.4 duyurusuna da <a href=\"https://wordpress.org/news/2018/02/wordpress-4-9-4-maintenance-release/\">buradan</a> ulaşabilirsiniz. Teknik detaylar ile ilgili çekirdek ekibin makalesine <a href=\"https://make.wordpress.org/core/2018/02/06/wordpress-4-9-4-release-the-technical-details/\">buradan</a> ulaşabilirsiniz.</p>\n<p>Yine her zaman olduğu gibi yükseltme yapmadan önce mutlaka veritabanınızın ve dosyalarınızın yedeğini almanızı öneriyoruz. Sürüm yükseltmeyle ilgili olarak sizi <a href=\"/belgeler/wordpress/wordpress-surum-yukseltme/\">sürüm yükseltme belgemiz</a>e yönlendirebiliriz.</p>\n<p>Yeni sürümle ilgili sorunlarınızı <a href=\"https://www.facebook.com/WPTurkiye/\">facebook</a> ya da <a href=\"https://twitter.com/WP_Turkiye/\">twitter</a> üzerinden paylaşabilir, Türkçe pakette bulduğunuz çeviri hatalarını ve çeviri hakkında önerilerinizi bize bildirebilirsiniz.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20207\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:66:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"WordPress Türkçe 4.8.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"https://www.wp-tr.org/wordpress-turkce-4-8-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 02 Aug 2017 21:30:46 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:14:\"Güncellemeler\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:5:\"4.8.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:18:\"WordPress Türkçe\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:24:\"WordPress Türkçe 4.8.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://www.wp-tr.org/?p=20193\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:469:\"Merhaba arkadaşlar, WordPress Türkçe 4.8.1 şu an indirilebilir durumda. 4.8 sürümünün 13 milyondan fazla kez indirilmesinden sonra bir bakım sürümü olarak 4.8.1&#8217;i duyurmaktan mutluluk duyuyoruz. Bu dağıtım 29 bakım düzeltmesi ve iyileştirmesinin yanı sıra, zengin metin bileşeninde düzeltmeler ve yeni Özel HTML bileşenini de içeriyor. Tüm değişiklikler için dağıtım notlarını inceleyebilir ya da değişiklik listesine [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Emre Erkan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:1925:\"<p><img loading=\"lazy\" decoding=\"async\" src=\"https://www.wp-tr.org/wp-content/uploads/2017/08/wp-tr-4-8-1.png\" alt=\"WordPress Türkçe 4.8.1\" width=\"670\" height=\"206\" class=\"aligncenter size-full wp-image-20194\" srcset=\"https://www.wp-tr.org/wp-content/uploads/2017/08/wp-tr-4-8-1.png 670w, https://www.wp-tr.org/wp-content/uploads/2017/08/wp-tr-4-8-1-200x61.png 200w\" sizes=\"auto, (max-width: 670px) 100vw, 670px\" /></p>\n<p>Merhaba arkadaşlar,</p>\n<p><a href=\"http://tr.wordpress.org/\"><img decoding=\"async\" src=\"/static/img/wp-indir-son.jpg\" alt=\"WordPress Türkiye indir\" align=\"left\" /></a>WordPress Türkçe 4.8.1 şu an <a href=\"http://tr.wordpress.org/\">indir</a>ilebilir durumda.</p>\n<p>4.8 sürümünün 13 milyondan fazla kez indirilmesinden sonra bir bakım sürümü olarak 4.8.1&#8217;i duyurmaktan mutluluk duyuyoruz.</p>\n<p>Bu dağıtım 29 bakım düzeltmesi ve iyileştirmesinin yanı sıra, zengin metin bileşeninde düzeltmeler ve yeni Özel HTML bileşenini de içeriyor. Tüm değişiklikler için <a href=\"https://codex.wordpress.org/Version_4.8.1\">dağıtım notları</a>nı inceleyebilir ya da <a href=\"https://core.trac.wordpress.org/query?milestone=4.8.1\">değişiklik listesi</a>ne bir göz atabilirsiniz.</p>\n<h2>Son olarak</h2>\n<p>WordPress.org üzerindeki resmi 4.8.1 duyurusuna da <a href=\"https://wordpress.org/news/2017/08/wordpress-4-8-1-maintenance-release/\">buradan</a> ulaşabilirsiniz.</p>\n<p>Yine her zaman olduğu gibi yükseltme yapmadan önce mutlaka veritabanınızın ve dosyalarınızın yedeğini almanızı öneriyoruz. Sürüm yükseltmeyle ilgili olarak sizi <a href=\"/belgeler/wordpress/wordpress-surum-yukseltme/\">sürüm yükseltme belgemiz</a>e yönlendirebiliriz.</p>\n<p>Yeni sürümle ilgili sorunlarınızı <a href=\"/forum/\">forumda</a> paylaşabilir, Türkçe pakette bulduğunuz çeviri hatalarını ve çeviri hakkında önerilerinizi bize bildirebilirsiniz.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"20193\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:27:\"https://www.wp-tr.org/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:4:\"site\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"67772354\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:20:{s:12:\"content-type\";s:23:\"text/xml; charset=utf-8\";s:4:\"vary\";s:46:\"Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site\";s:12:\"feedburnerv2\";s:0:\"\";s:13:\"last-modified\";s:29:\"Sun, 18 Oct 2026 17:32:37 GMT\";s:13:\"cache-control\";s:46:\"no-cache, no-store, max-age=0, must-revalidate\";s:6:\"pragma\";s:8:\"no-cache\";s:7:\"expires\";s:29:\"Mon, 01 Jan 1990 00:00:00 GMT\";s:4:\"date\";s:29:\"Mon, 09 Nov 2026 15:18:28 GMT\";s:9:\"accept-ch\";s:192:\"Sec-CH-UA-Arch, Sec-CH-UA-Bitness, Sec-CH-UA-Full-Version, Sec-CH-UA-Full-Version-List, Sec-CH-UA-Model, Sec-CH-UA-WoW64, Sec-CH-UA-Form-Factors, Sec-CH-UA-Platform, Sec-CH-UA-Platform-Version\";s:18:\"permissions-policy\";s:174:\"ch-ua-arch=*, ch-ua-bitness=*, ch-ua-full-version=*, ch-ua-full-version-list=*, ch-ua-model=*, ch-ua-wow64=*, ch-ua-form-factors=*, ch-ua-platform=*, ch-ua-platform-version=*\";s:28:\"cross-origin-resource-pol