(374, '_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9', 'a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"Open Channels FM: The Value of Blogging for Yourself\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565719\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://openchannels.fm/the-value-of-blogging-for-yourself/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"Treat your blog as a personal space first: share thoughts, links, photos, and everyday moments without chasing engagement, building an enduring archive for reflection and growth.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 09 Nov 2026 11:06:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"Dave Smith: Using Claude to rebuild my website on…WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://aheadcreative.co.uk/?p=1325\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://aheadcreative.co.uk/articles/using-claude-to-rebuild-my-website-onwordpress/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:504:\"<p>This is the first post on my new website which is still proudly powered by WordPress. Yes, WordPress. I know it’s trending these days to talk about using Claude to build static sites with a markdown “database” and how that’s made your site better and faster. But guess what? This website is also built by Claude. And guess what? It’s fast. You know what else?</p>\n<p><a href=\"https://aheadcreative.co.uk/articles/using-claude-to-rebuild-my-website-onwordpress/\" rel=\"nofollow\">Source</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 08 Nov 2026 09:29:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dave Smith\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:135:\"Gutenberg Times: WordPress 7.1.4, Gutenberg 24.3, a new Studio workspace, WordPress for the Agentic Web, and more—Weekend Edition 379\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=47411\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:140:\"https://gutenbergtimes.com/wordpress-7-1-4-gutenberg-24-3-a-new-studio-workspace-wordpress-for-the-agentic-web-and-more-weekend-edition-379/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:32267:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">First things first: if you haven&#8217;t updated to <a href=\"https://wordpress.org/news/2026/10/wordpress-7-1-4/\"><strong>WordPress 7.1.4</strong></a>, do that before reading any further. The October 28 security release fixes more than a dozen issues, including a weakness in the upgrade process that could lead to remote code execution and stored XSS in several blocks and the Interactivity API. The fixes were backported all the way to the 4.7 branch, so don&#8217;t forget about those older sites you maintain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Running a store? WooCommerce had a busy week, too. <a href=\"https://developer.woocommerce.com/2026/11/04/woocommerce-11-2-2-release-notes/\"><strong>WooCommerce 11.2.2</strong></a> is a security release with a database update, and there&#8217;s a separate <a href=\"https://developer.woocommerce.com/2026/11/03/security-update-for-woopayments/\"><strong>security update for WooPayments</strong></a> with a table of fixed versions for each release line.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As for me, I&#8217;m just enjoying the autumn weather. It feels like we&#8217;ve finally shed off the days of summer heat in Alabama. And that means it&#8217;s fall festival season. I&#8217;ll see if I can find one or two to enjoy in the coming weeks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">With that, let&#8217;s get down to the latest news.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your friendly neighborhood developer advocate, <img alt=\"🍂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f342.png\" style=\"height: 1em;\" /><br /><em>Justin Tadlock</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#getting-ready-for-wordpress-7-2\">Getting ready for WordPress 7.2</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#feature-notifications-get-a-design-and-some-pushback\">Feature Notifications get a design, and some pushback</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#prototypes-from-dave-on-wp\">Prototypes from Dave on WP</a></li></ul></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#what-s-new-in-playground\">What&#039;s new in Playground?</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#ai-in-wordpress\">AI in WordPress</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 is one step closer. <strong>David Baumwald</strong> announced <a href=\"https://wordpress.org/news/2026/11/wordpress-7-2-beta-4/\"><strong>WordPress 7.2 Beta 4</strong></a> on November 3. Beta 3 shipped inside the 7.1.4 security release. This round continues the work on the Abilities API and DataViews extensibility, and it improves focus visibility in Windows High Contrast mode. Translation updates also show up individually on the Updates screen now, so you can choose which ones to install. <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-2/\"><strong>Beta 2</strong></a> laid the groundwork for much of this, adding server-side registration for DataViews and DataForm and moving the admin to SVG icons.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The final release is still set for December 8. Spin up the <a href=\"https://playground.wordpress.net/release\">Beta 4 Playground instance to test</a>, or run <code>wp core update --version=7.2-beta4</code> on a staging site.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Formatting no longer stops at the edge of a block. In <a href=\"https://make.wordpress.org/core/2026/11/02/whats-new-in-gutenberg-24-3-28-october/\"><strong>What&#8217;s new in Gutenberg 24.3</strong></a>, <strong>George Mamadashvili</strong> shows how you can now select text across several blocks and format all of it at once. Notes pick up emoji reactions, and the Media inserter moves onto the same DataViews component behind the Site Editor&#8217;s lists. Failed saves finally explain themselves, too, with a copy button for sharing the details. The release carries the security fixes from 7.1.4, so update the plugin if you run it. The 24.4 release candidate followed on November 3.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"getting-ready-for-wordpress-7-2\"><strong>Getting ready for WordPress 7.2</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Dashicons are on their way out of the admin bar and menu. In WordPress 7.2, those icons are inline SVGs, and <strong>Ashar Fuadi</strong> explains <a href=\"https://make.wordpress.org/core/2026/11/05/svg-icons-in-the-admin-bar-and-menu-in-wordpress-7-2/\"><strong>what the SVG icon change means for plugins and themes</strong></a>. Most code needs nothing. But admin color schemes and anything that styles or hides icons through <code>::before</code> will need a small CSS update, and the post has before-and-after rules you can copy. There&#8217;s a new API, too: <code>add_menu_page()</code>, <code>register_post_type()</code>, and admin bar nodes now accept a registered icon name like <code>core-admin/pin</code>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Visit <code>/random/</code> on a 7.2 site, and you&#8217;ll land on a random published post. <strong>Aaron Jorbin</strong> details <a href=\"https://make.wordpress.org/core/2026/11/05/your-content-is-going-to-get-more-random/\"><strong>the new random content endpoint</strong></a>, which also works for categories, tags, authors, and custom post types. It&#8217;s on by default, with a new <code>randomable</code> argument for post types and a <code>wp_enable_random_content_redirect</code> filter to switch it off.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It hasn&#8217;t landed quietly. Dozens of comments push back on the on-by-default choice, citing hidden content that could surface (Core still has no <code>noindex</code> option), <code>ORDER BY RAND()</code> load on large sites, and agencies now facing an must-use plugin across hundreds of sites. <strong>Matt Mullenweg</strong> has since agreed it shouldn&#8217;t use the page URL structure, so expect changes before 7.2 ships.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Anne McCarthy</strong> pulled several features still in development into one prototype for <a href=\"https://nomad.blog/2026/11/02/imagining-the-near-future-of-collaboration-in-wordpress/\"><strong>imagining the near future of collaboration in WordPress</strong></a>. It combines the 7.2 Notes features, suggestion mode, and the Presence API with a small workflow plugin that blocks publishing until every open note and suggestion is resolved. She purposely left real-time collaboration out to show how much works without it. She also shares the full prompt she used. Borrow it and build the demo yourself. Watch for an upcoming call for testing on suggestions.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"feature-notifications-get-a-design-and-some-pushback\"><strong>Feature Notifications get a design, and some pushback</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Plugins have spent years shouting over each other with admin notices. <a href=\"https://make.wordpress.org/core/2026/10/29/exploring-a-design-for-feature-notifications/\"><strong>Exploring a design for Feature Notifications</strong></a>, from <strong>Poli Gilad</strong>, proposes a single notification bell on every admin screen, in the editor, and on the front of the site, with plugins sending data rather than layout. Existing admin notices keep working.</p>\n\n\n\n<figure class=\"wp-block-image size-full has-custom-border\"><img alt=\"Screenshot of proposed feature notifications dropdown with tabs for different types of notifications.\" class=\"has-border-color has-accent-6-border-color wp-image-47434\" height=\"1338\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/11/feature-notifications-proposal.webp?resize=1776%2C1338&#038;ssl=1\" style=\"border-width: 1px;\" width=\"1776\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">That last point drew the most criticism. <strong>Matt Mullenweg</strong> argued that the proposal does nothing about today&#8217;s notice spam and that the fix needs directory guidelines, enforcement, and incentives, not only a new interface. He backed <strong>David Perez&#8217;s</strong> suggestion that plugins declare each notice&#8217;s intent (operational, setup, or promotional) as a requirement.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the code side, <strong>Jonathan Bossenger&#8217;s</strong> <a href=\"https://make.wordpress.org/core/2026/11/01/wp-feature-notifications-weekly-update-2026-10-30/\"><strong>weekly update for October 30</strong></a> reports that the notification repository is now scoped per user, laying the groundwork for the REST API. Prefer to watch the work happen? His <a href=\"https://www.youtube.com/watch?v=Qt6zujtlBVk\"><strong>Friday live stream</strong></a> includes testing the plugin in Studio and the AI-assisted workflow he uses for reviewing PRs. He also holds office hours in the Feature Notifications Slack channel on Thursdays at 10:00 UTC.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<h3 class=\"wp-block-heading\" id=\"prototypes-from-dave-on-wp\"><strong>Prototypes from Dave on WP</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The block toolbar has picked up a lot of buttons over the years. <strong>Dave Smith</strong> asks <a href=\"https://www.youtube.com/watch?v=Hja-5ercQ-Q\"><strong>whether this is the end of the block toolbar</strong></a> and demos a consolidated version inside his Create Not Learn prototype editor. In about eight minutes, you&#8217;ll see how grouping those controls could make everyday formatting quicker and more consistent without giving up any of the editor&#8217;s power. The video description has a Playground link, so you can click around it yourself.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-4-3 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">He also took a <a href=\"https://www.youtube.com/watch?v=nZNfuQSxyN0\"><strong>first look at drag-and-drop grid building</strong></a>, pulling Andrei Draganescu&#8217;s work-in-progress free-form grid into the same prototype. You can drag, resize, snap, and rotate blocks on a grid, and that demo has its own Playground link.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Release roadmap posts have kept roughly the same shape for three years. <strong>Anne McCarthy</strong> wants to know whether they still work, and she&#8217;s asking everyone from Core committers and extenders to hosts and everyday users to <a href=\"https://make.wordpress.org/core/2026/10/26/release-roadmap-survey/\"><strong>help shape future release roadmaps</strong></a> by November 16.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Studio is now built around a conversation. <strong>Rich Tabor</strong> introduced <a href=\"https://wordpress.com/blog/2026/11/04/wordpress-studio-workspace/\"><strong>a new workspace for building with WordPress</strong></a>, where you describe the site you want and an AI agent builds a first version next to a live preview. It offers four looks, then four layouts, and saves your choices to a <code>DESIGN.md</code> file so later chats keep the same design. You can pin notes on the preview with Annotate, bring your own Anthropic API key, or connect Claude Code, Codex, or Cursor over MCP. It&#8217;s a free desktop app for macOS, Windows, and Linux.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For a hands-on take, <strong>Elliott Richmond</strong> writes up <a href=\"https://elliottrichmond.co.uk/wordpress-studio-new-workspace-is-out-whats-changed-since-my-first-look/\"><strong>what&#8217;s changed since his first look</strong></a>, along with one fair caution: the agent can now edit your live site directly, so building locally first is still the safer habit. Rich also shared <a href=\"https://richtabor.com/studio/\"><strong>why he rebuilt Studio</strong></a> on his own blog, and <strong>Nick Diego</strong> recorded a <a href=\"https://x.com/nickmdiego/status/2118020671938900064\"><strong>quick video overview</strong></a> of the new design and agentic features.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Stores running WooCommerce&#8217;s Purple theme are about to get more design control. In the <a href=\"https://developer.woocommerce.com/2026/10/26/woocommerce-11-3-pre-release/\"><strong>WooCommerce 11.3 pre-release post</strong></a>, <strong>Brian Coords</strong> highlights color, spacing, and border controls curated for each block, including Product, Featured Product, Featured Category, and Product Categories List. The On-Sale Badge block can show the discount as an amount, a percentage, or custom text, and Product Gallery swiping on mobile now follows your finger naturally. The beta is out now, with the final release scheduled for the week of November 9.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Two new short tutorials from WordPress.com cover blocks you&#8217;ll use on nearly every site. The <a href=\"https://www.youtube.com/watch?v=Zi9r3kmfehI\"><strong>Columns block walkthrough</strong></a> builds grids, feature sections, and pricing tables, including column widths and stacking on mobile. </p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://www.youtube.com/watch?v=p7H59fW4_U0\"><strong>Query Loop block video</strong></a> shows how to choose which posts appear, then sort and filter them, in about two minutes. Bookmark both for the next time a client asks how it&#8217;s done.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Ipsum, the default theme shipping with WordPress 7.2, is easy to mistake for a simple theme. <strong>Carlo Daniele&#8217;s</strong> <a href=\"https://kinsta.com/blog/ipsum-wordpress-theme/\"><strong>dive into the Ipsum theme and how to extend it</strong></a> for Kinsta shows what&#8217;s underneath. Templates hand their layouts to hidden patterns, around 60 patterns ship with it, and the default text colors reach a WCAG AAA contrast ratio. </p>\n\n\n\n<p class=\"wp-block-paragraph\">My favorite detail is its use of the Block Bindings API: a comments call to action changes its text depending on whether the post already has comments.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-142e4ecc64159a71 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">PHPStan can&#8217;t check a call to a class it has never seen, so code that integrates with other WooCommerce extensions usually gets skipped or baselined. <strong>Ján Mikláš</strong> introduces <a href=\"https://developer.woocommerce.com/2026/11/03/php-stubs-for-extensions/\"><strong>automated PHP stubs for Woo extensions</strong></a>, a <code>woocommerce/php-stubs</code> package generated from extensions on the WooCommerce Marketplace and WordPress.org. The stubs are public on GitHub and Packagist. If your plugin or theme talks to other Woo extensions, you can check those calls without installing every extension in your analysis environment.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WooCommerce 11.3 fixes a confusing count for stores that sell bundles. When an extension adds a product to the cart as part of a bundle, the Product Button says &#8220;1 in cart&#8221; even though the shopper never added it on its own. <strong>Luis Herranz</strong> explains <a href=\"https://developer.woocommerce.com/2026/10/27/cart-item-children/\"><strong>declaring parent-child cart item relationships</strong></a> through a new <code>woocommerce_store_api_cart_item_parent_item_key</code> filter and a <code>parent_item_key</code> field in the Store API. WooCommerce never marks items as children by itself, so it&#8217;s up to your extension to declare them. Today only the button count uses it, but the Cart and Mini-Cart blocks could someday nest child items under their parents.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\"><strong>What&#8217;s new in Playground?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can now test changes on a copy of your real site without a local server. <strong>Fellyph Cintra</strong> details how to <a href=\"https://make.wordpress.org/playground/2026/11/04/clone-your-wordpress-site-in-playground-with-reprint/\"><strong>clone your WordPress site in Playground with Reprint</strong></a>. Install the Reprint plugin on your live site, authorize Playground with a migration key, and you&#8217;ll have an editable copy in your browser. Nothing you change there gets published to your live site. It&#8217;s handy for trying a design change, checking a plugin update, or tracking down a bug. Not ready to connect your own site? The post links to a public demo you can clone first.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Playground&#8217;s building blocks aren&#8217;t only for WordPress anymore. In <a href=\"https://make.wordpress.org/playground/2026/10/23/joomla-playground-shared-php-tools-beyond-wordpress/\"><strong>Joomla Playground: shared PHP tools beyond WordPress</strong></a>, <strong>Fellyph Cintra</strong> looks at Herman Peeren&#8217;s community project, which runs Joomla in a browser tab on the same <code>@php-wasm</code> packages and <code>mysql-on-sqlite</code> library. The interesting part is what comes back to WordPress. A different CMS sends different queries and workloads through those shared tools, surfacing compatibility and performance issues both projects can fix.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\"><strong>AI in WordPress</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Imagine telling your AI agent, &#8220;Help me with my example.com site,&#8221; and it recognizes WordPress, asks you to authorize it, and gets to work. That&#8217;s the experience behind <a href=\"https://make.wordpress.org/ai/2026/10/28/wordpress-for-the-agentic-web/\"><strong>WordPress for the Agentic Web</strong></a>, the AI team&#8217;s plan from <strong>Jason Adams</strong>. It lays out four areas of work: a more reliable MCP Adapter that could move into Core, a baseline set of Abilities for common site tasks, OAuth so you don&#8217;t have to paste Application Passwords into an agent, and an end-to-end user experience tying them together. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The 7.2 cycle lays the foundation, and 7.3 is the target. Each area still needs a lead, so now&#8217;s the time to raise your hand. Not everyone in the comments is sold on MCP-first, though. <strong>Adrian Mörchen</strong> argued that most agents already work fine over the REST API and that filling its gaps should come first, and Jason replied that Abilities serve both routes. The <a href=\"https://make.wordpress.org/ai/2026/11/02/ai-contributor-weekly-summary-28-october-2026/\"><strong>October 28 contributor summary</strong></a> covers the first discussion, with <strong>Tammie Lister</strong> volunteering to lead UX, and The Repository has <a href=\"https://www.therepository.email/wordpress-ai-team-lays-out-ambitious-four-part-plan-to-make-wordpress-agent-ready-by-7-3\"><strong>its own take on the plan</strong></a>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Six new experiments landed in <a href=\"https://make.wordpress.org/ai/2026/11/02/whats-new-in-ai-1-5-0/\"><strong>AI 1.5.0</strong></a>, the canonical AI plugin, and <strong>Jeffrey Paul</strong> breaks down each one. Text to Speech generates an audio version of a post, and Content Verification detects C2PA Content Credentials in uploaded images. MCP Access installs the MCP Adapter and adds a <strong>Tools → MCP Access</strong> screen where you decide which Abilities agents can see. The other three are WebMCP, Revision Change Summary, and Block Container Label Generation. If you&#8217;re following the Agentic Web work, MCP Access is the one to try first.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Through the end of November, free WordPress.com sites can <a href=\"https://wordpress.com/blog/2026/11/03/free-chatgpt-claude/\"><strong>connect to ChatGPT or Claude at no cost</strong></a>. Full access normally comes with a paid plan. <strong>Alexa Peduzzi</strong> notes that both connections run on MCP, so after a one-time setup you can ask your AI to save a draft, clear out comments, or suggest what to fix this week. The post includes ready-made prompts that open in either tool. <em>Not interested?</em> Connecting is entirely optional, and a WordPress.com reply in the comments points to the separate <strong>Prevent third-party sharing</strong> setting for anyone worried about AI training on their content.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">AI prototypes that ignore the design system keep landing on designers&#8217; desks. In <a href=\"https://automattic.design/2026/10/27/working-towards-higher-quality-agentic-experiences/\"><strong>working towards higher-quality agentic experiences</strong></a>, <strong>@leilabyron</strong> shares the 13 best practices Automattic Design wrote for agentic interfaces, grouped under capturing intent, showing the work, and building trust. The guidance doesn&#8217;t stop at a list: an agentic-design-brief skill picks the practices that matter for a feature, and an AGENTS.md file gives coding agents explicit rules. One rule worth stealing: ask when the request is genuinely ambiguous, and don&#8217;t ask when the answer is already clear.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">What happens when an AI feature gives a wrong answer or lets a prompt injection slip through? At WordPress Day for AI Faro 2026, <strong>Ivelina Dimova</strong> shared how to use <a href=\"https://wordpress.tv/2026/10/28/ai-with-boundaries-implementing-guardrails-and-evals-in-wordpress/\"><strong>guardrails and evals for AI features in WordPress</strong></a> to test quality before anything reaches production. Anyone adding AI features to client sites should pair it with the Automattic Design post above. The slides are linked from the video page.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-099721d606b87bbd wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-840914561e185658 wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 07 Nov 2026 17:45:24 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"WordCamp Central: A Shoutout to Meahadi Hasan: From the Classroom to the Global WordPress Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16691960\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"https://central.wordcamp.org/news/2026/11/a-shoutout-to-meahadi-hasan-from-the-classroom-to-the-global-wordpress-community/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:12474:\"<p class=\"wp-block-paragraph\"><strong>Learning becomes more meaningful when students get the opportunity to put their knowledge into practice.</strong> For <a href=\"https://profiles.wordpress.org/meahadi/\" rel=\"noopener\" target=\"_blank\">Meahadi Hasan</a>, WordPress Credits opened the door to opportunities beyond website development. He explored photography contributions, participated in community initiatives like Campus Connect, and contributed to Bengali translations through the Polyglots and Training Teams, becoming an active part of the global WordPress community.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Meahadi is a final-year Computer Science and Engineering student at <a href=\"https://pundrauniversity.ac.bd/\" rel=\"noopener\" target=\"_blank\">Pundra University of Science &amp; Technology</a>, Bangladesh. He joined the WordPress Credits Program in August 2026 as part of his university&#8217;s Industrial Training (Internship) course. On 2 November 2026, he successfully completed the program, but his journey was about much more than earning a certificate.<br /></p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><a href=\"https://central.wordcamp.org/files/2026/11/meahadi.png\"><img alt=\"\" class=\"wp-image-16691961\" height=\"224\" src=\"https://central.wordcamp.org/files/2026/11/meahadi.png\" width=\"224\" /></a></figure>\n</div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Rediscovering WordPress and Exploring New Opportunities</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Meahadi first encountered WordPress in 2020 through YouTube tutorials, where he learned to build a basic website. However, he didn&#8217;t continue working with it regularly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Joining WordPress Credits gave him an opportunity to explore WordPress from a completely different perspective. He discovered that WordPress is not just a website-building platform; it is a global open-source community where people with different skills can contribute.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He chose four contribution teams that matched his interests: Photos, Polyglots, Community and Training.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>66 Photographs and Contributions Beyond Development</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">One of Meahadi&#8217;s most remarkable achievements was his contribution to the WordPress Photo Directory.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He initially set a target of publishing 30 photographs. He went beyond that goal and successfully published <strong>66 original CC0-licensed photographs</strong>, featuring nature, plants, landscapes, and everyday scenes from Bangladesh.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>A Selection of Meahadi’s Photo Contributions</strong></p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Fish-scaled.jpg\"><img alt=\"Fish\" class=\"wp-image-16691966\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/Fish-771x1024.jpg\" width=\"771\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/flower-2-scaled.jpg\"><img alt=\"flower 2\" class=\"wp-image-16691967\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/flower-2-768x1024.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/flower-one-scaled.jpg\"><img alt=\"flower one\" class=\"wp-image-16691968\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/flower-one-768x1024.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Nature-2-scaled.jpg\"><img alt=\"Nature 2\" class=\"wp-image-16691969\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/Nature-2-847x1024.jpg\" width=\"847\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Nature-3.jpg\"><img alt=\"Nature 3\" class=\"wp-image-16691970\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/Nature-3-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Nature-scaled.jpg\"><img alt=\"Nature\" class=\"wp-image-16691971\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/Nature-846x1024.jpg\" width=\"846\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/brown-land-snail-edited-scaled.jpg\"><img alt=\"brown land snail\" class=\"wp-image-16691972\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/brown-land-snail-edited-927x1024.jpg\" width=\"927\" /></a></figure>\n</figure>\n\n\n\n<p class=\"has-text-align-center wp-block-paragraph\"><a href=\"https://wordpress.org/photos/author/meahadi/\" rel=\"noopener\" target=\"_blank\">Explore Meahadi&#8217;s Photo Directory contributions</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>His journey didn&#8217;t stop with photography. He also:</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Contributed Bengali translation suggestions through the Polyglots Team.</li>\n\n\n\n<li>Prepared a Bengali translation of the Learn WordPress lesson <em>The WordPress Ecosystem</em>, currently available for review.</li>\n\n\n\n<li>Built his personal website at <a href=\"https://meahadi.blog/\">meahadi.blog</a></li>\n\n\n\n<li>Participated in WordPress Slack, GitHub, and Make WordPress community discussions.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">These experiences helped him understand how people with different skills collaborate to make WordPress better.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Achievements</strong></h2>\n\n\n\n<div class=\"wp-block-columns has-white-color has-text-color has-link-color wp-elements-5 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-6 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #fff3cd;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-7\"><strong>60+</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Photos published</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Photo Directory</strong></p>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-8 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #e8f5e9;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-9\"><strong>400+</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">String Translated</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Polyglots Team</strong></p>\n</div>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 35px;\"></div>\n\n\n\n<div class=\"wp-block-columns has-white-color has-text-color has-link-color wp-elements-10 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-11 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #e3f2fd;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-12\"><strong>1</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Lesson Translated</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Training Team</strong></p>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-13 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #fce4ec;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-14\"><strong>1</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Portfolio Created</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress.Com</strong></p>\n</div>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 35px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Learning Through Mentorship and Community</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Throughout the program, Meahadi received guidance from his assigned mentor, <strong><a href=\"https://profiles.wordpress.org/wprashed/\" rel=\"noopener\" target=\"_blank\">Rashed Hossain</a></strong>, who helped him navigate the learning process and contribution workflows.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><a href=\"https://profiles.wordpress.org/devmuhib/\" rel=\"noopener\" target=\"_blank\">Muhibul Haque</a></strong> also shared useful resources and advice, particularly around the Training Team.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Through practical assignments, documentation, community discussions, and real contributions, Meahadi developed confidence in WordPress, translation workflows, documentation, and communicating with contributors.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Looking back on his experience, he shared that he previously viewed WordPress mainly as a platform for building websites. Now, he understands the many opportunities available within its global community, even beyond writing code.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>What&#8217;s Next?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Completing WordPress Credits is not the end of Meahadi&#8217;s journey.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He plans to continue contributing photographs, improve his Bengali translation skills, explore more Learn WordPress localization opportunities, and participate more actively in the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">His advice to future students is simple: start with a contribution team that matches your interests, read the handbooks, ask questions, and focus on small, consistent contributions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As he reminds us, the biggest value of WordPress Credits is not just completing a course; it&#8217;s becoming part of a community where your contributions can be genuinely useful.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Celebrating More Than Course Completion</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Meahadi&#8217;s journey reflects what we hope to achieve through WordPress Credits: helping students move beyond theoretical learning, develop practical skills, discover their potential, and become active members of the global WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">His story shows that you don&#8217;t have to be a developer to make a meaningful contribution. Whether through photography, translation, community, or development, there is a place for everyone in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Congratulations, Meahadi, on completing WordPress Credits and making your mark in the WordPress community. This is just the beginning!</strong> <img alt=\"🎉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f389.png\" style=\"height: 1em;\" /></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Nov 2026 12:27:01 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Muhibul Haque\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"Dave Smith: How AI-ready is WordPress in 2026?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://aheadcreative.co.uk/?p=1364\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://aheadcreative.co.uk/articles/how-ai-ready-is-wordpress-in-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:517:\"<p>It’s nearly the end of 2026 and I want to use my agent with WordPress already (like…yesterday)! To do this we need to understand exactly how “AI ready” WordPress is. This post outlines where things stand from my perspective and why I think it’s critically important for the future of the platform. Not yet, but it’s getting there quickly. This is what you can and can’t do today…</p>\n<p><a href=\"https://aheadcreative.co.uk/articles/how-ai-ready-is-wordpress-in-2026/\" rel=\"nofollow\">Source</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Nov 2026 11:11:45 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dave Smith\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"Open Channels FM: The Work After the Easy Part, Open Channels News Week in Review\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566647\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://openchannels.fm/the-work-after-the-easy-part-open-channels-news-week-in-review/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:281:\"This week’s Open Channels News covers actively exploited vulnerabilities, AI-driven coding and bug discovery, open-source funding pressures, workforce cuts, data-tax concerns, archival tools, and the continuing need for careful maintenance, verification, and sustainable support.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Nov 2026 09:27:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"Open Channels FM: SUSE Cuts Jobs as AI Grows, E2E Fuels Open Source Testing and Drupal Seeks Sustainable Support\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566590\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:118:\"https://openchannels.fm/suse-cuts-jobs-as-ai-grows-e2e-fuels-open-source-testing-and-drupal-seeks-sustainable-support/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:134:\"SUSE navigates AI-driven job cuts, E2E gains traction in software validation, and Drupal weighs new approaches for shared maintenance.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Nov 2026 14:27:40 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"Open Channels FM: The Lost Art of Exploring the Web\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a: